package com.erp.reimbursement.controller; import com.erp.reimbursement.dto.AuthDtos.*; import com.erp.reimbursement.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService s;public AuthController(AuthService s){this.s=s;} @PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){return s.login(r);} @PostMapping("/signup") public ResponseEntity<?> signup(@Valid @RequestBody SignupRequest r){var u=s.signup(r);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","Signup successful","employeeId",u.getEmployeeId()));} @PostMapping("/forgot-password/send-otp") public Map<String,String> otp(@Valid @RequestBody OtpRequest r){s.sendOtp(r);return Map.of("message","OTP generated. Configure SMS/email provider for production delivery.");} @PostMapping("/forgot-password/reset") public Map<String,String> reset(@Valid @RequestBody ResetPasswordRequest r){s.reset(r);return Map.of("message","Password reset successfully");} @GetMapping("/me") public Map<String,Object> me(org.springframework.security.core.Authentication a){return Map.of("username",a.getName());}}
